// One plan window, as the provider last described it.
type SessionLimitWindow struct {
	// The window is spent: the provider refused a request on it, or reported 100% or
	// more.
	Hit bool `json:"hit"`

	// `5h`, `7d`, or the window's length for any other (`1d`, `90m`).
	Name string `json:"name"`

	// Unix seconds. Absent when the provider did not say.
	ResetsAt int64 `json:"resetsAt,omitempty"`

	// As the provider reported it, unrounded; it can exceed 100.
	UsedPercent float64 `json:"usedPercent"`
}

// The plan windows of the account this session's assistant runs on: an
// account-level reading shared by every session of that assistant (the Swift
// app's `AssistantQuota.machineLimits`), not this conversation's. An empty
// `windows` is "nobody said", never 0%.
type SessionLimits struct {
	// Unix seconds of the provider record the windows came from. Absent when nothing
	// has been read.
	At int64 `json:"at,omitempty"`

	// Unix milliseconds when this daemon took the reading. A client holding readings
	// from several answers keeps the newest by this. Absent for a session with no
	// assistant.
	ReadAtMs int64                `json:"readAtMs,omitempty"`
	Windows  []SessionLimitWindow `json:"windows"`
}

// The question on a waiting session's screen, as rows a finger can hit (the
// Swift app's menuObject). Present only on a waiting session whose screen could
// be read as a menu; a waiting row without it is a question drawn in a shape
// nothing recognised. The row labels and details may be refilled from the
// session's own transcript, but only once the screen proves which question it
// is showing; the numbers, the caret, Submit and the steps are always the
// screen's.
type SessionMenu struct {
	Options []SessionMenuOption `json:"options"`

	// The prose above the rows, or the question as the call asked it. Absent when it
	// could not be read.
	Question string `json:"question,omitempty"`

	// The number of the row the caret is on. Absent when it is on none of them — a
	// multi-select's button can hold it.
	Selected int64 `json:"selected,omitempty"`

	// Where this question sits in a set of them, as the picker's tab bar draws it.
	// Absent for a lone question.
	Steps  []SessionMenuStep  `json:"steps,omitempty"`
	Submit *SessionMenuSubmit `json:"submit,omitempty"`
}

// One row. `n` is the keystroke and not the position: the page sends that
// number to `POST /v1/sessions/{id}/key`, and renumbering would make a button
// answer a different question than its label says.
type SessionMenuOption struct {
	// Whether a keystroke reaches this row (1…9). A row that cannot be answered is
	// drawn and not offered.
	Can bool `json:"can"`

	// Only on a multi-select, where a row ticks rather than answers; present and false
	// is a real answer (the daemon writes it through its own wire type, since a
	// generated optional bool would drop false).
	Checked bool `json:"checked,omitempty"`

	// The prose under the label, joined.
	Detail string `json:"detail,omitempty"`
	Label  string `json:"label"`
	N      int64  `json:"n"`

	// The caret is on this row, so it is what a bare Return would confirm.
	Selected bool `json:"selected"`
}

// One question of a set, as the picker's tab bar names it.
type SessionMenuStep struct {
	// What was chosen, once the picker's review screen names it.
	Answer string `json:"answer,omitempty"`
	Done   bool   `json:"done"`
	Label  string `json:"label"`
}

// The button under a multi-select's rows. It has no number on screen; `POST
// /key` takes the word `submit` for it.
type SessionMenuSubmit struct {
	Label    string `json:"label"`
	Selected bool   `json:"selected"`
}

// One model this session's assistant can be switched to. A session's current
// model is matched against `id` by prefix, so a dated id still finds its row;
// `name` is what a reader is shown for it.
type SessionModel struct {
	Command string `json:"command"`
	ID      string `json:"id"`
	Name    string `json:"name"`
}

// One assistant session. Fields that cannot be supported are absent rather than
// invented; a reader that handles absence handles this too.
type SessionRow struct {
	Assistant    Assistant            `json:"assistant,omitempty"`
	Backend      Backend              `json:"backend"`
	Closeability Closeability         `json:"closeability"`
	Coordination *SessionCoordination `json:"coordination,omitempty"`
	Coordinator  *SessionCoordinator  `json:"coordinator,omitempty"`
	CWD          string               `json:"cwd,omitempty"`
	Disposition  *WorkDisposition     `json:"disposition,omitempty"`
	Evidence     Evidence             `json:"evidence"`
	Icon         *Icon                `json:"icon,omitempty"`
	ID           string               `json:"id"`
	IsClaude     bool                 `json:"isClaude"`

	// What the session is called, by the Swift app's rungs (ITerm.swift
	// preferredDisplayLabel): a name typed in Clawdline (the Swift store's config.json
	// `session_titles`), the title of the task, handoff or Feature Root Clawdline
	// opened the tab for (orchestrator.json), the conversation's own title (`/rename`,
	// else `aiTitle`), Codex's thread name or an automatic title, Claude Code's
	// registry handle — the first that has something. Never a terminal title. Absent
	// when nothing names the session.
	Label string `json:"label,omitempty"`

	// What a working session says it is doing, read from its screen with the
	// assistant's own clock in it. Present while working; on a waiting session with a
	// menu it is instead that menu's revision (the Swift app's menuRevision), which no
	// row draws and which changes whenever the question does. The Swift app sends it
	// under this name and the row's height depends on it.
	Line           string                `json:"line,omitempty"`
	Menu           *SessionMenu          `json:"menu,omitempty"`
	Owed           *WorkOwed             `json:"owed,omitempty"`
	RootAssignment *RootAssignmentRecord `json:"root_assignment,omitempty"`

	// The assistant's own conversation id, when one was recovered from its command
	// line.
	SessionID string `json:"sessionId,omitempty"`

	// The commands this session left running in the background, newest first, at most
	// six. Absent rather than empty when there are none, as the Swift app sends it;
	// always absent for Codex, which keeps no record of them.
	Shells []SessionShell `json:"shells,omitempty"`
	State  SessionState   `json:"state"`
	TTY    string         `json:"tty,omitempty"`

	// Who the declaring session said will move it — a session id, or a person.
	WorkMovedBy string `json:"work_moved_by,omitempty"`

	// The session's own words for its state, present only when its declaration decided
	// `work_state` (then `work_provenance` is `self`).
	WorkNote string `json:"work_note,omitempty"`

	// Whether that mover is a person. Absent unless the declaration decided the state;
	// present and false is a real answer.
	WorkPersonNeeded bool           `json:"work_person_needed,omitempty"`
	WorkProvenance   WorkProvenance `json:"work_provenance,omitempty"`

	// Unix seconds: when that declaration was made.
	WorkSince int64     `json:"work_since,omitempty"`
	WorkState WorkState `json:"work_state"`
}

// One background command a session started and has not finished: its output
// file has no ending written under it, and the session's transcript announced
// its id as a background command. `at` is when it last printed something.
type SessionShell struct {
	// Unix seconds.
	At int64 `json:"at"`

	// The command line that started it, on one line. Absent when the two transcript
	// records it is joined from straddled a read.
	Command string `json:"command,omitempty"`

	// The last line it printed, clipped to 160 characters.
	Doing string `json:"doing,omitempty"`

	// Claude Code's own id for it.
	ID string `json:"id"`

	// The description written beside the command, when there was one.
	What string `json:"what,omitempty"`
}

// What the session appears to be doing. `unknown` is a real answer and is never
// flattened into `idle`.
type SessionState string

const (
	SessionStateWorking SessionState = "working"
	SessionStateWaiting SessionState = "waiting"
	SessionStateIdle    SessionState = "idle"
	SessionStateUnknown SessionState = "unknown"
)

// SessionStateValues is every value the contract allows, in contract order.
var SessionStateValues = []SessionState{SessionStateWorking, SessionStateWaiting, SessionStateIdle, SessionStateUnknown}

type SessionsSnapshot struct {
	At       int64        `json:"at"`
	Scan     Scan         `json:"scan"`
	Sessions []SessionRow `json:"sessions"`
}

// The keys to change. A null key is left as it is.
type SettingsRequest struct {
	// `claude` or `codex`.
	AutoNameAssistant *string `json:"auto_name_assistant"`

	// 0 to 1.
	Backdrop *float64 `json:"backdrop"`

	// 0 to 1.
	CardOpacity *float64 `json:"card_opacity"`

	// Whether a new session is named by an assistant.
	CodexAutoName *bool `json:"codex_auto_name"`

	// Whether the terminal selects the tab the bar points at.
	FollowTarget *bool `json:"follow_target"`

	// A combination the shell can register (`cmd+shift+k`), or empty for none.
	Hotkey *string `json:"hotkey"`

	// `auto` or a language tag the catalog resolves.
	Language *string `json:"language"`

	// A pack name the shell offers.
	Mascot *string `json:"mascot"`

	// Whether a mascot lives in the notch.
	Notch *bool `json:"notch"`

	// Whether an agent may push a sentence of its own.
	OrchestratorAgentNotify *bool `json:"orchestrator_agent_notify"`

	// 0, 180 or -1.
	OrchestratorChildLinger *int64 `json:"orchestrator_child_linger"`

	// Whether one session may hand work to another.
	OrchestratorEnabled *bool `json:"orchestrator_enabled"`

	// 1 to 10.
	OrchestratorMaxChildren *int64 `json:"orchestrator_max_children"`

	// Whether a finished child types a line back into the session that sent it.
	OrchestratorNotifyRoot *bool `json:"orchestrator_notify_root"`

	// `ask`, `edits` or `full`.
	OrchestratorPermission *string `json:"orchestrator_permission"`

	// A font family name.
	OutputFont *string `json:"output_font"`

	// 80 to 900.
	OutputHeight *float64 `json:"output_height"`

	// `auto`, `transcript` or `terminal`.
	OutputMode *string `json:"output_mode"`

	// Whether the reading pane puts the newest first.
	OutputNewestFirst *bool `json:"output_newest_first"`

	// 8 to 28.
	OutputSize *float64 `json:"output_size"`

	// Notify when a session reports a delivery.
	PushOnDelivery *bool `json:"push_on_delivery"`

	// Notify when a deploy ends, either way.
	PushOnDeploy *bool `json:"push_on_deploy"`

	// Notify when a whole batch of dispatched work ends.
	PushOnFanout *bool `json:"push_on_fanout"`

	// Whether anything but this Mac may read the session list.
	Remote *bool `json:"remote"`

	// A hostname, or empty.
	RemoteHostname *string `json:"remote_hostname"`

	// `off`, `quick` or `named`.
	RemoteTunnel *string `json:"remote_tunnel"`

	// Whether a paired device may write into a session.
	RemoteWrite *bool `json:"remote_write"`

	// Whether the bar comes back with the terminal.
	ReopenOnReturn *bool `json:"reopen_on_return"`

	// Bundle identifiers separated by commas, or empty for every app.
	ScopeApp *string `json:"scope_app"`

	// Have a model write the sentence a notification carries.
	SmartNotifications *bool `json:"smart_notifications"`

	// `auto`, `iterm` or `tmux`.
	Terminal *string `json:"terminal"`

	// `auto`, `apple` or `whisper`.
	VoiceEngine *string `json:"voice_engine"`

	// 0 to 30.
	VoiceSettleSeconds *float64 `json:"voice_settle_seconds"`

	// 0 to 300.
	VoiceStopSeconds *float64 `json:"voice_stop_seconds"`

	// 360 to 1400.
	Width *float64 `json:"width"`

	// 0.05 to 0.80.
	YFraction *float64 `json:"y_fraction"`
}

type SettingsSnapshot struct {
	// Whose quota that naming turn spends, `claude` or `codex`. Remembered while the
	// switch above is off, so turning it back on does not quietly change providers.
	AutoNameAssistant *string `json:"auto_name_assistant"`

	// How much the bar blurs what is behind it.
	Backdrop *float64 `json:"backdrop"`

	// The bar card's opacity.
	CardOpacity *float64 `json:"card_opacity"`

	// Whether a new session is named by an assistant. The Swift app's spelling, kept
	// so a line copied between the two files means the same thing.
	CodexAutoName *bool `json:"codex_auto_name"`

	// False before anything has been written. Every key then has the shell's default.
	Exists bool `json:"exists"`

	// Whether the terminal selects the tab the bar points at.
	FollowTarget *bool `json:"follow_target"`

	// The file's `hotkey`, or null when the file does not carry one as a string. Null
	// and empty both register nothing in this app: the Swift app is running and owns
	// option+space.
	Hotkey *string `json:"hotkey"`

	// `auto`, or one of the catalog's tags (`zh-Hant`, `en`, …). This build ships
	// only zh-Hant; the key is written so a later one can read it.
	Language *string `json:"language"`

	// Which mascot pack the shell draws.
	Mascot *string `json:"mascot"`

	// Whether a mascot lives in the notch.
	Notch *bool `json:"notch"`

	// The file's `on_state_change`, the argv this app runs when a session changes
	// state. Read only here: it is an argument list, not a command line, and a single
	// text box invites exactly the word-splitting that would break a path with a space
	// in it. Absent is an empty list.
	OnStateChange []string `json:"on_state_change,omitempty"`

	// Whether an agent may push a sentence of its own.
	OrchestratorAgentNotify *bool `json:"orchestrator_agent_notify"`

	// What becomes of a child's tab after it reports: 0 closes it, 180 waits three
	// minutes, -1 keeps it.
	OrchestratorChildLinger *int64 `json:"orchestrator_child_linger"`

	// Whether one session may hand work to another.
	OrchestratorEnabled *bool `json:"orchestrator_enabled"`

	// How many child sessions one session may run at once, 1 to 10.
	OrchestratorMaxChildren *int64 `json:"orchestrator_max_children"`

	// Whether a finished child types a line back into the session that sent it.
	OrchestratorNotifyRoot *bool `json:"orchestrator_notify_root"`

	// How far a child may go on its own: `ask`, `edits` or `full`.
	OrchestratorPermission *string `json:"orchestrator_permission"`

	// The reading pane's face. Monospaced, because the pane draws a terminal.
	OutputFont *string `json:"output_font"`

	// The reading pane's height in points.
	OutputHeight *float64 `json:"output_height"`

	// What the reading pane shows: `auto`, `transcript` or `terminal`.
	OutputMode *string `json:"output_mode"`

	// Whether the reading pane puts the newest first.
	OutputNewestFirst *bool `json:"output_newest_first"`

	// The reading pane's text size in points.
	OutputSize *float64 `json:"output_size"`

	// Where the file is, whether or not it exists.
	Path string `json:"path"`

	// Notify when a session reports a delivery.
	PushOnDelivery *bool `json:"push_on_delivery"`

	// Notify when a deploy ends, either way.
	PushOnDeploy *bool `json:"push_on_deploy"`

	// Notify when a whole batch of dispatched work ends.
	PushOnFanout *bool `json:"push_on_fanout"`

	// Whether anything but this Mac may read the session list.
	Remote *bool `json:"remote"`

	// The hostname a named tunnel answers on.
	RemoteHostname *string `json:"remote_hostname"`

	// `off`, `quick` or `named`.
	RemoteTunnel *string `json:"remote_tunnel"`

	// Whether a paired device may write into a session.
	RemoteWrite *bool `json:"remote_write"`

	// Whether the bar comes back with the terminal.
	ReopenOnReturn *bool `json:"reopen_on_return"`

	// The file's `scope_app`, or null when absent — which the shell reads as
	// com.googlecode.iterm2. Empty is every app.
	ScopeApp *string `json:"scope_app"`

	// Have a model write the sentence a notification carries.
	SmartNotifications *bool `json:"smart_notifications"`

	// Where a new session opens: `auto`, `iterm` or `tmux`. Not the same question as
	// scope_app.
	Terminal *string `json:"terminal"`

	// `auto`, `apple` or `whisper`.
	VoiceEngine *string `json:"voice_engine"`

	// How long a pause ends a sentence. 0 is off.
	VoiceSettleSeconds *float64 `json:"voice_settle_seconds"`

	// How long a silence ends the whole turn. 0 is off.
	VoiceStopSeconds *float64 `json:"voice_stop_seconds"`

	// The bar's width in points.
	Width *float64 `json:"width"`

	// Where the bar's top sits, as a fraction of screen height.
	YFraction *float64 `json:"y_fraction"`
}

// Whether the task has written a result yet. `settled` false is not a failure;
// it means nothing has been written, which is the ordinary state of work still
// in progress.
type SettleResult struct {
	OK      bool      `json:"ok"`
	Settled bool      `json:"settled"`
	State   TaskState `json:"state,omitempty"`
	TaskID  string    `json:"task_id"`
}

// A new or adopted token, twice: here for a script, and in `Set-Cookie:
// clawdline-next=…; Path=/; Max-Age=31536000; HttpOnly; SameSite=Strict`
// (plus `; Secure` behind an HTTPS proxy) for a page.
type SignedIn struct {
	OK    bool   `json:"ok"`
	Token string `json:"token"`
}

type StartAssistant struct {
	Availability StartAvailability `json:"availability"`
	ID           string            `json:"id"`
	Label        string            `json:"label"`
}

// AssistantQuota.Availability. This daemon reads no quota, so it answers
// unknown.
type StartAvailability string

const (
	StartAvailabilityOK        StartAvailability = "ok"
	StartAvailabilityLow       StartAvailability = "low"
	StartAvailabilityExhausted StartAvailability = "exhausted"
	StartAvailabilityUnknown   StartAvailability = "unknown"
)

// StartAvailabilityValues is every value the contract allows, in contract order.
var StartAvailabilityValues = []StartAvailability{StartAvailabilityOK, StartAvailabilityLow, StartAvailabilityExhausted, StartAvailabilityUnknown}

// One directory a session can be started in. `id` is sixteen hex characters of
// the path's SHA-256 and is the only part a client sends back; `path` is here
// so two projects with one name can be told apart.
type StartPlace struct {
	// When this place was last worked in, Unix seconds.
	At    int64  `json:"at"`
	Icon  *Icon  `json:"icon,omitempty"`
	ID    string `json:"id"`
	Label string `json:"label"`
	Path  string `json:"path"`
}

// GET /v1/places: recorded Claude Code folders, Codex rollouts and live
// sessions' directories, deduplicated, still on disk, newest first, at most
// forty.
type StartPlaceList struct {
	Assistants []StartAssistant `json:"assistants"`
	At         int64            `json:"at"`
	Places     []StartPlace     `json:"places"`
}

// Whether the Swift app's store was read for this answer: `current`; `stale`,
// an earlier reading carried because the newest one was half-written; or
// `unknown`, nothing could be read. Unknown is never the same as empty.
type StoreReading string

const (
	StoreReadingCurrent StoreReading = "current"
	StoreReadingStale   StoreReading = "stale"
	StoreReadingUnknown StoreReading = "unknown"
)

// StoreReadingValues is every value the contract allows, in contract order.
var StoreReadingValues = []StoreReading{StoreReadingCurrent, StoreReadingStale, StoreReadingUnknown}

// One stored picture and the literal to paste into a reply to show it:
// `<clawdline-image id="…">`.
type StoredImage struct {
	ByteCount int64  `json:"byte_count"`
	ExpiresAt int64  `json:"expires_at"`
	Height    int64  `json:"height"`
	ID        string `json:"id"`
	Marker    string `json:"marker"`
	MediaType string `json:"media_type"`
	Width     int64  `json:"width"`
}

// The tab the task was opened in.
type TaskChild struct {
	Backend    string `json:"backend,omitempty"`
	SessionID  string `json:"sessionId,omitempty"`
	TerminalID string `json:"terminalId,omitempty"`
}

// `at` is when the answer was built. With `store` at `unknown` the list holds
// only this daemon's own tasks, which is not the same as the machine having no
// others.
type TaskList struct {
	At    int64        `json:"at"`
	Page  TaskPage     `json:"page"`
	Store StoreReading `json:"store"`
	Tasks []TaskRow    `json:"tasks"`
}

// Which finished tasks this answer carries. Unfinished ones ride on every page.
type TaskPage struct {
	Cursor   int64  `json:"cursor"`
	Fields   string `json:"fields"`
	Finished int64  `json:"finished"`
	Limit    int64  `json:"limit"`

	// Where the next page starts. The Swift app sends null on the last page; here the
	// key is absent.
	NextCursor int64 `json:"nextCursor,omitempty"`
	Unfinished int64 `json:"unfinished"`
}

// The session that asked for the task. `terminalId` is not stored: it is
// resolved on every read against the sessions on screen — the parent task's
// child terminal first, otherwise the one live session whose conversation is
// `sessionId` — and is absent when that is not exactly one.
type TaskRoot struct {
	Assistant  string `json:"assistant,omitempty"`
	Label      string `json:"label,omitempty"`
	SessionID  string `json:"sessionId,omitempty"`
	TaskID     string `json:"taskId,omitempty"`
	TerminalID string `json:"terminalId,omitempty"`
}

// One task. The camelCase keys are the Swift app's list projection, which the
// copied console reads (`view/derive.js`: id, title, state, created,
// finishedAt, child, root, usage). The four snake_case keys `task_id`,
// `project_dir`, `created_at` and `claims` are this daemon's older names, kept
// beside them because the Dashboard panel still reads them. The Swift app's
// `projectDir` is sent only as `project_dir`: the generator gives both
// spellings one Go name, and the copied console reads neither. `claims` is
// therefore always present here, where the Swift app leaves it out when none
// were declared (`claims_declared` says which). Omitted from the Swift
// projection because no page here reads them: worktree (its presence is
// `isolation`), executor, completion_delivery, verification, landing,
// landing_paths, terminal_intervention, released_claims, respawn_of,
// waiting_on.
type TaskRow struct {
	Artifacts      []string   `json:"artifacts,omitempty"`
	Assistant      Assistant  `json:"assistant"`
	AttachSession  string     `json:"attachSession,omitempty"`
	Attached       bool       `json:"attached,omitempty"`
	BriefedAt      int64      `json:"briefedAt,omitempty"`
	Child          *TaskChild `json:"child,omitempty"`
	Claims         []string   `json:"claims"`
	ClaimsDeclared bool       `json:"claims_declared"`

	// Unix seconds.
	Created int64 `json:"created"`

	// Unix seconds; the same instant as `created`.
	CreatedAt        int64      `json:"created_at"`
	Depth            int64      `json:"depth"`
	Dir              string     `json:"dir"`
	FinishedAt       int64      `json:"finishedAt,omitempty"`
	ID               string     `json:"id"`
	Isolation        string     `json:"isolation,omitempty"`
	Kind             string     `json:"kind"`
	Model            string     `json:"model,omitempty"`
	Permission       string     `json:"permission"`
	ProjectDir       string     `json:"project_dir"`
	ReasoningEffort  string     `json:"reasoning_effort,omitempty"`
	ResultVerifiedAt int64      `json:"resultVerifiedAt,omitempty"`
	Root             *TaskRoot  `json:"root,omitempty"`
	ScheduleID       string     `json:"schedule_id,omitempty"`
	SessionRoot      bool       `json:"session_root,omitempty"`
	SpawnedAt        int64      `json:"spawnedAt,omitempty"`
	State            TaskState  `json:"state"`
	TaskID           string     `json:"task_id"`
	Title            string     `json:"title"`
	UntouchedClaims  []string   `json:"untouched_claims,omitempty"`
	Usage            *TaskUsage `json:"usage,omitempty"`
	WorkItemID       string     `json:"workItemId,omitempty"`
	WorkPhase        string     `json:"workPhase,omitempty"`
}

type TaskState string

const (
	TaskStateQueued      TaskState = "queued"
	TaskStateSpawning    TaskState = "spawning"
	TaskStateBriefed     TaskState = "briefed"
	TaskStateSuccess     TaskState = "success"
	TaskStateFailure     TaskState = "failure"
	TaskStateTimeout     TaskState = "timeout"
	TaskStateCancelled   TaskState = "cancelled"
	TaskStateSpawnFailed TaskState = "spawn_failed"
)

// TaskStateValues is every value the contract allows, in contract order.
var TaskStateValues = []TaskState{TaskStateQueued, TaskStateSpawning, TaskStateBriefed, TaskStateSuccess, TaskStateFailure, TaskStateTimeout, TaskStateCancelled, TaskStateSpawnFailed}

// What the child spent. `costUsd` is absent where nothing priced it, which is
// always the case for Codex.
type TaskUsage struct {
	CacheRead  int64   `json:"cacheRead"`
	CacheWrite int64   `json:"cacheWrite"`
	CostUsd    float64 `json:"costUsd,omitempty"`
	Input      int64   `json:"input"`
	Model      string  `json:"model,omitempty"`
	Output     int64   `json:"output"`
	Total      int64   `json:"total"`
}

type TranscriptAction struct {
	Command string `json:"command,omitempty"`

	// read or search.
	Kind  string `json:"kind"`
	Name  string `json:"name,omitempty"`
	Path  string `json:"path,omitempty"`
	Query string `json:"query,omitempty"`
}

// What a Codex tool item recorded about itself: `called` for an MCP call with a
// title, `explored` for a shell command Codex classified as reads and searches.
type TranscriptActivity struct {
	Actions []TranscriptAction `json:"actions"`

	// How long the item took. -1 when the record did not say, which the Swift app
	// sends as an absent key; 0 is a real, sub-millisecond duration and is drawn as
	// one.
	DurationMs int64  `json:"durationMs"`
	Kind       string `json:"kind"`

	// A called tool's result text, cut at 4,000 characters.
	Result string `json:"result,omitempty"`

	// inProgress, pending, completed or failed.
	Status string `json:"status,omitempty"`
	Title  string `json:"title,omitempty"`
}

// One thing in a conversation, in the shape the Swift app's `transcriptRows`
// writes it. A tool call and what the tool returned both carry `role: tool`;
// only the call names its tool. A call's `text` is the one line describing what
// it was asked to do — a command, a path, a query — which is what a folded
// row shows as its subject. An `AskUserQuestion` call carries its questions
// instead, after the U+0001 `ask` U+0001 marker.
type TranscriptEntry struct {
	Activity *TranscriptActivity `json:"activity,omitempty"`

	// Pictures an assistant turn showed with a `<clawdline-image>` marker, or a
	// Clawdline session message carried. Resolved against this daemon's store and
	// then, read-only, the Swift app's.
	Artifacts []ImageArtifact `json:"artifacts,omitempty"`

	// Unix seconds. Absent when the record carried no timestamp this reader accepts.
	At int64 `json:"at,omitempty"`

	// Exact edits: a Codex patch, or the whole file a Claude `Write` created. Absent
	// on every other entry.
	FileChanges []TranscriptFileChange `json:"fileChanges,omitempty"`

	// Images attached to a user turn. Absent when there were none: the Swift app
	// writes an explicit 0 on user rows, and a reader treats absence as that 0.
	ImageCount int64             `json:"imageCount,omitempty"`
	Notice     *TranscriptNotice `json:"notice,omitempty"`

	// A complete Codex checklist update.
	Plan []TranscriptPlanStep `json:"plan,omitempty"`

	// user, assistant, peer (another Claude Code session), message (another session
	// through Clawdline), notice (Clawdline about a task) or tool.
	Role string `json:"role"`

	// The human-facing name of the session a peer or message row came from.
	Source string `json:"source,omitempty"`

	// Which assistant sent a Clawdline session message.
	SourceAssistant string `json:"sourceAssistant,omitempty"`

	// How a peer or message row arrived: the peer's own mode, or `clawdline`.
	SourceMode string `json:"sourceMode,omitempty"`
	Text       string `json:"text"`

	// The tool a call used. Absent on a tool's result and on prose.
	Tool string `json:"tool,omitempty"`
}

type TranscriptFileChange struct {
	// The whole file, for an addition, a deletion or a Claude `Write`.
	Content string `json:"content,omitempty"`

	// add, delete, update or write, as the record spelled it; `change` when it did
	// not.
	Kind        string `json:"kind"`
	MovePath    string `json:"movePath,omitempty"`
	Path        string `json:"path"`
	UnifiedDiff string `json:"unifiedDiff,omitempty"`
}

// A decoded Clawdline notice without its protocol, version and body — the
// Swift app's `webObject`. Which fields are present depends on `kind`:
// task_finished, workspace_overlap, file_wait_request, file_wait_release or
// handoff_receipt.
type TranscriptNotice struct {
	AckPath   string `json:"ack_path,omitempty"`
	Assistant string `json:"assistant,omitempty"`
	Audience  string `json:"audience,omitempty"`

	// Present only when true.
	ChildMayStillWrite bool `json:"child_may_still_write,omitempty"`

	// Present only when true.
	ClaimsReleased bool   `json:"claims_released,omitempty"`
	Commit         string `json:"commit,omitempty"`
	HandoffID      string `json:"handoff_id,omitempty"`
	Kind           string `json:"kind"`
	Note           string `json:"note,omitempty"`
	NoticeID       string `json:"notice_id,omitempty"`

	// task_finished only, where the decoder requires it, so absence there means 0.
	Outstanding      int64                     `json:"outstanding,omitempty"`
	Overlaps         []TranscriptNoticeOverlap `json:"overlaps,omitempty"`
	Paths            []string                  `json:"paths,omitempty"`
	ProjectDir       string                    `json:"project_dir,omitempty"`
	Reason           string                    `json:"reason,omitempty"`
	ReleaseCondition string                    `json:"release_condition,omitempty"`
	Repository       string                    `json:"repository,omitempty"`
	ResultPath       string                    `json:"result_path,omitempty"`
	State            string                    `json:"state,omitempty"`
	Task             *TranscriptNoticeTask     `json:"task,omitempty"`
	Title            string                    `json:"title,omitempty"`
	WaitID           string                    `json:"wait_id,omitempty"`
	WaiterSessionID  string                    `json:"waiter_session_id,omitempty"`
}

type TranscriptNoticeOverlap struct {
	Path string               `json:"path"`
	Task TranscriptNoticeTask `json:"task"`
}

type TranscriptNoticeTask struct {
	ID    string `json:"id"`
	Title string `json:"title"`
}

// `entries`, `signature` and `truncation` are the Swift app's transcript
// payload; `evidence`, `path` and `note` say where the reading came from.
type TranscriptPage struct {
	// Oldest first.
	Entries  []TranscriptEntry `json:"entries"`
	Evidence Evidence          `json:"evidence"`
	ID       string            `json:"id"`
	Note     string            `json:"note,omitempty"`

	// Which file this was read from. A reading that cannot name its source is not
	// evidence.
	Path string `json:"path,omitempty"`

	// The record's size and modification time, `<bytes>-<unix seconds>`, and empty
	// when nothing was read. It changes whenever the entries could have.
	Signature  string                `json:"signature"`
	Truncation *TranscriptTruncation `json:"truncation,omitempty"`
}

type TranscriptPlanStep struct {
	// pending, inProgress or completed — Codex app-server's spelling, not the
	// rollout's in_progress.
	Status string `json:"status"`
	Step   string `json:"step"`
}

// The newest entries were kept and older ones left out, because the whole page
// would have passed its byte budget.
type TranscriptTruncation struct {
	BudgetBytes         int64 `json:"budgetBytes"`
	EntriesOmittedCount int64 `json:"entriesOmittedCount"`

	// transcript_byte_budget.
	Reason string `json:"reason"`
}

// The Swift app's `UsageQueryService` payload. The lossless `.json` export is
// this object unwrapped, with every matched row, `truncated`, and no
// `pagination`.
type UsageAnalytics struct {
	Availability   AnalyticsAvailability    `json:"availability"`
	Breakdown      []AnalyticsBreakdown     `json:"breakdown"`
	Bucket         string                   `json:"bucket"`
	Capabilities   AnalyticsCapabilities    `json:"capabilities"`
	Corrections    int64                    `json:"corrections"`
	Coverage       AnalyticsCoverageSummary `json:"coverage"`
	Freshness      AnalyticsFreshness       `json:"freshness"`
	GroupBy        string                   `json:"groupBy"`
	Pagination     *AnalyticsPagination     `json:"pagination,omitempty"`
	Portfolio      AnalyticsPortfolio       `json:"portfolio"`
	PriceSnapshot  AnalyticsPriceSnapshot   `json:"priceSnapshot"`
	Range          AnalyticsRange           `json:"range"`
	RangeFreshness AnalyticsRangeFreshness  `json:"rangeFreshness"`
	RowCount       int64                    `json:"rowCount"`
	Rows           []AnalyticsRow           `json:"rows"`
	SchemaVersion  int64                    `json:"schemaVersion"`
	Totals         AnalyticsSummary         `json:"totals"`
	Trend          []AnalyticsTrendBucket   `json:"trend"`

	// The `.json` export only.
	Truncated             bool                           `json:"truncated,omitempty"`
	UnavailableDimensions AnalyticsUnavailableDimensions `json:"unavailableDimensions"`

	// overview or agent_work; echoed only.
	View string `json:"view"`
}

// A refused Usage read.
type UsageAnalyticsRefusal struct {
	Error UsageAnalyticsRefusalBody `json:"error"`
}

// The Swift app's refusal envelope, which the Usage page reads its code from.
// Codes: bad_request, usage_analytics_busy (503, with Retry-After),
// export_too_large (413), json_serialization_failed, ambiguous_project (409),
// project_not_found (404).
type UsageAnalyticsRefusalBody struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

// GET /v1/orchestrator/usage/analytics.
type UsageAnalyticsReply struct {
	Usage UsageAnalytics `json:"usage"`
}

type UsageReport struct {
	At       int64      `json:"at"`
	Sessions []UsageRow `json:"sessions"`

	// The sum of the rows that could be read. Rows carrying `evidence: none`
	// contribute nothing, so this can be smaller than the truth and never larger.
	TotalTokens int64 `json:"totalTokens"`
}

// One session's usage, as its own transcript records it. This is what the
// transcript accounts for, which is a smaller claim than what the session
// spent: one conversation's own turns cannot see work another model did on its
// behalf.
type UsageRow struct {
	Assistant Assistant `json:"assistant,omitempty"`
	Evidence  Evidence  `json:"evidence"`
	ID        string    `json:"id"`
	Label     string    `json:"label,omitempty"`

	// How many assistant turns were counted. Absent for a source that reports a
	// cumulative total rather than per-turn figures.
	Messages int64        `json:"messages,omitempty"`
	Models   []ModelUsage `json:"models"`

	// Why a row could not be read. Present with `evidence: none`, and never alongside
	// a number.
	Note        string `json:"note,omitempty"`
	TotalTokens int64  `json:"totalTokens"`
}

// A refusal from this route. It is the ordinary refusal shape with one field
// added, because `no_whisper` covers two different afternoons: `brew install
// whisper-cpp` leaves a machine with the binary and no model, and a page told
// only "no whisper" sends somebody to check the thing they already did.
type VoiceRefusal struct {
	Detail string `json:"detail"`
	Error  string `json:"error"`

	// Only on `no_whisper`: `no_binary` or `no_model`.
	Reason string `json:"reason,omitempty"`
}

// A recording, already in the one shape whisper.cpp takes. The resampling is
// done in the browser because that is the one format question every browser can
// answer about itself — what it just recorded — while this machine has no
// ffmpeg and could not open an Opus file if it wanted to.
type VoiceRequest struct {
	// Base64 of little-endian 16-bit mono PCM. A minute of it is about 2.6MB encoded.
	Audio string `json:"audio"`

	// Must be 16000. Checked rather than resampled: a body that names 48000 has not
	// made a small mistake, it has sent something that would transcribe as a voice
	// three times too fast, and quietly resampling somebody's voice is a worse answer
	// than saying no.
	Rate int64 `json:"rate"`
}

// What was said, and how long this machine took to read it. An empty `text` is
// an answer and not a failure: whisper heard the recording and there were no
// words in it, which happens to a pocket and to a room that went quiet.
type VoiceResult struct {
	Ms   int64  `json:"ms"`
	Text string `json:"text"`
}

// What a finished row delivered, present only with `milestone_complete` or
// `work_complete`. `scope` is `session` for a session's own delivery receipt
// and `task` for the task that opened it; the landing fields are present only
// when a broker-verified landing backs `work_complete`.
type WorkDisposition struct {
	Commit       string `json:"commit,omitempty"`
	Evidence     string `json:"evidence"`
	LandedAt     int64  `json:"landedAt,omitempty"`
	ReceiptAt    int64  `json:"receiptAt,omitempty"`
	Scope        string `json:"scope"`
	Target       string `json:"target,omitempty"`
	TargetCommit string `json:"targetCommit,omitempty"`
	TaskID       string `json:"taskId,omitempty"`
	Title        string `json:"title"`
}

// Something this session declared it is owed, beside whatever its work state
// is.
type WorkOwed struct {
	MovedBy      string `json:"moved_by,omitempty"`
	Note         string `json:"note"`
	PersonNeeded bool   `json:"person_needed"`
	Provenance   string `json:"provenance"`
	Since        int64  `json:"since"`
}

// Who decided a row's work state. `broker` means it was projected from what
// could be read; `self` means the session's own declaration (the Swift store's
// `session_self_states`) is what decided it.
type WorkProvenance string

const (
	WorkProvenanceBroker WorkProvenance = "broker"
	WorkProvenanceSelf   WorkProvenance = "self"
)

// WorkProvenanceValues is every value the contract allows, in contract order.
var WorkProvenanceValues = []WorkProvenance{WorkProvenanceBroker, WorkProvenanceSelf}

// One projection of what this session needs, ranked so a reader can sort by it.
// `unknown` outranks nothing and means the inputs were incomplete.
type WorkState string

const (
	WorkStateReady             WorkState = "ready"
	WorkStateWorking           WorkState = "working"
	WorkStateHolding           WorkState = "holding"
	WorkStateWaitingYou        WorkState = "waiting_you"
	WorkStateWaitingSession    WorkState = "waiting_session"
	WorkStateUnknown           WorkState = "unknown"
	WorkStateMilestoneComplete WorkState = "milestone_complete"
	WorkStateWorkComplete      WorkState = "work_complete"
)

// WorkStateValues is every value the contract allows, in contract order.
var WorkStateValues = []WorkState{WorkStateReady, WorkStateWorking, WorkStateHolding, WorkStateWaitingYou, WorkStateWaitingSession, WorkStateUnknown, WorkStateMilestoneComplete, WorkStateWorkComplete}

type WorktreeCanonical struct {
	Error      *WorktreeIssue           `json:"error"`
	ObservedAt string                   `json:"observedAt"`
	Oid        string                   `json:"oid"`
	Ref        string                   `json:"ref"`
	State      WorktreeObservationState `json:"state"`
}

type WorktreeClass string

const (
	WorktreeClassActiveInUse               WorktreeClass = "active_in_use"
	WorktreeClassLandedIdenticalResidue    WorktreeClass = "landed_identical_residue"
	WorktreeClassGenuinelyUnlanded         WorktreeClass = "genuinely_unlanded"
	WorktreeClassMixedConflicted           WorktreeClass = "mixed_conflicted"
	WorktreeClassTaskOwnedTemporary        WorktreeClass = "task_owned_temporary"
	WorktreeClassPrunableStaleMetadata     WorktreeClass = "prunable_stale_metadata"
	WorktreeClassUnknownIncompleteEvidence WorktreeClass = "unknown_incomplete_evidence"
)

// WorktreeClassValues is every value the contract allows, in contract order.
